+package com.huawei.oss.wireless.experienceassuranceservice.venuealloc.impl.service;
+
+import static org.mockito.Matchers.any;
+import static org.mockito.Matchers.anyString;
+import static org.mockito.Mockito.times;
+import static org.mockito.Mockito.verify;
+import static org.mockito.Mockito.when;
+
+import com.huawei.cloudsop.mockito.adapter.PowerMockRunnerJava21;
+import com.huawei.oss.wireless.experienceassuranceservice.venuealloc.impl.mapper.ScenesMgrDBMapper;
+
+import org.junit.Test;
+import org.junit.runner.RunWith;
+import org.mockito.InjectMocks;
+import org.mockito.Mock;
+import org.mockito.Mockito;
+import org.powermock.core.classloader.annotations.PowerMockIgnore;
+import org.powermock.core.classloader.annotations.PrepareForTest;
+
+/**
+ * SceneTaskLockServiceImpl test class with verify functionality
+ */
+@RunWith(PowerMockRunnerJava21.class)
+@PowerMockIgnore({"javax.management.*", "jdk.internal.reflect.*"})
+@PrepareForTest({
+    SceneTaskLockServiceImpl.class
+})
+public class SceneTaskLockServiceImplTest {
+    @InjectMocks private SceneTaskLockServiceImpl sceneTaskLockServiceImpl;
+
+    @Mock private ScenesMgrDBMapper scenesMgrDBMapper;
+
+    @Test()
+    public void testRunTaskWhenNormalLockThenSuccess() {
+        Mockito.when(scenesMgrDBMapper.clearExpiredLocks(anyString(), anyString())).thenReturn(0);
+        sceneTaskLockServiceImpl.runTask();
+        verify(scenesMgrDBMapper, times(2)).clearExpiredLocks(anyString(), anyString());
+    }
+
+    @Test()
+    public void testRunTaskWhenAbnormalLockThenSuccess() {
+        when(scenesMgrDBMapper.clearExpiredLocks(anyString(), anyString())).thenReturn(1);
+        sceneTaskLockServiceImpl.runTask();
+        verify(scenesMgrDBMapper, times(2)).clearExpiredLocks(anyString(), anyString());
+    }
+
+    @Test()
+    public void testRunTaskWhenQueryDatabaseErrorThenWriteLog() {
+        when(scenesMgrDBMapper.clearExpiredLocks(anyString(), anyString())).thenThrow(new RuntimeException("query database error"));
+        sceneTaskLockServiceImpl.runTask();
+        verify(scenesMgrDBMapper, times(1)).clearExpiredLocks(anyString(), anyString());
+    }
+}
